// Runtime services called by the recompiled PPU code (generated by "sly4_recomp emit").
//
// Generated functions have the signature void f_XXXXXXXX(PPUContext&, GuestMemory&) and
// map guest calls/returns onto C++ calls/returns. Whatever cannot be resolved statically
// (bctrl/blrl, calls into code without a generated function) goes through call_indirect,
// which looks the target up in the function table and otherwise runs the interpreter.
#pragma once

#include <cstddef>
#include <cstdint>

#include "cpu/ppu_context.h"
#include "memory/guest_memory.h"

namespace sly4::rt {

using GenFn = void (*)(PPUContext&, GuestMemory&);
struct FnEntry {
    uint32_t addr;
    GenFn fn;
};

// Registered by the generated table (sorted by address).
void set_function_table(const FnEntry* table, size_t count);
GenFn find_function(uint32_t addr);
const FnEntry* function_table(size_t& count);

// Calls guest code at `target`; LR already holds the return address.
void call_indirect(PPUContext& c, GuestMemory& m, uint32_t target);
// Interpreter fallback: runs from `entry` until a blr comes back to the current LR.
void interpret_until_return(PPUContext& c, GuestMemory& m, uint32_t entry);
// How often code outside the generated table ran in the interpreter (summary).
void interpreter_stats(uint64_t& calls, uint64_t& steps);

void syscall(PPUContext& c, GuestMemory& m);                               // c.cia: after the sc
void trap(PPUContext& c, GuestMemory& m);                                  // c.cia: the trap
void invalid(PPUContext& c, GuestMemory& m);                               // c.cia: the bad word
void bad_jump(PPUContext& c, GuestMemory& m, uint32_t from, uint32_t target);  // jump table miss
void lr_mismatch(PPUContext& c, GuestMemory& m, uint32_t at, uint32_t expected);
void budget_exceeded(PPUContext& c, GuestMemory& m);

// The kernel installs the syscall handler and the HLE range (phase 3); tests install a
// fault handler that abandons the current case. Defaults: syscall -> r3 = CELL_ENOSYS,
// fault -> log + abort.
struct Hooks {
    void (*syscall)(PPUContext&, GuestMemory&) = nullptr;
    void (*fault)(PPUContext&, GuestMemory&, const char* what) = nullptr;
    void (*lr_mismatch)(PPUContext&, GuestMemory&, uint32_t at, uint32_t expected) = nullptr;
    // Calls and branches to [hle_base, hle_base + hle_size) run a native library function
    // instead of guest code; the function returns to LR like a blr.
    void (*hle)(PPUContext&, GuestMemory&, uint32_t target) = nullptr;
    uint32_t hle_base = 0, hle_size = 0;
};
Hooks& hooks();

}  // namespace sly4::rt
